"""f0.3 identity gate: every pushed ref (branches and tags) is scanned.

Verified defects this file pins down:

* the pre-push hook generated by scripts/install-hooks.sh only ran push_gate.sh
  for refs/heads/main|master, so tags and every other branch were never
  scanned (the public f0.2 tag object carries a tagger address on a private
  IPv4 host);
* scripts/commit_metadata_scan.py only read commit author/committer, never an
  annotated tag's tagger;
* its forbidden-domain rule only knew numeric IPv4 and ``.local``, so
  ``ops@build-01.internal`` or an Aliyun default host name passed.

Every behaviour test here runs real git in throw-away repositories under
tmp_path, and each fix is paired with a negative control showing that the
previous code let the same fixture through.
"""

from __future__ import annotations

import os
import re
import shutil
import subprocess
import sys
from pathlib import Path

import pytest

from scripts import commit_metadata_scan as cms

ROOT = Path(__file__).resolve().parents[1]
SCRIPTS = ROOT / "scripts"
CLEAN = ("monkey2jack", "monkey2jack@users.noreply.github.com")
WORD = "synthetic-private-fragment-7c41"
# 扫描报告的原文字段：被拦要能分清「判了红」与「扫描器崩了」。
FORBIDDEN_HIT = re.compile("禁止邮箱域=[1-9]")
NOT_ALLOWLISTED_HIT = re.compile("白名单外身份=[1-9]")
UNVERIFIABLE = "提交元数据扫描：不可核验"


# --------------------------------------------------------------------------
# Negative-control copies of the previous implementation (faaa9af).
# --------------------------------------------------------------------------

_OLD_NUMERIC_IPV4 = re.compile(rb"(?:[0-9]{1,3}\.){3}[0-9]{1,3}")


def _old_forbidden_email_domain(email: bytes) -> bool:
    """Verbatim copy of the faaa9af rule (numeric IPv4 and .local only)."""
    if email.count(b"@") != 1:
        return True
    domain = email.rsplit(b"@", 1)[1].lower().rstrip(b".")
    if domain.startswith(b"[") and domain.endswith(b"]"):
        domain = domain[1:-1]
    return (
        not domain
        or not bool(re.fullmatch(rb"[a-z0-9.-]+", domain))
        or any(not label or label.startswith(b"-") or label.endswith(b"-")
               for label in domain.split(b"."))
        or bool(_OLD_NUMERIC_IPV4.fullmatch(domain))
        or domain == b"local"
        or domain.endswith(b".local")
    )


# Control flow of the faaa9af pre-push hook: only main/master reached the gate.
_OLD_HOOK = """#!/usr/bin/env bash
# aidumei-pre-push-hook (faaa9af control flow)
while read -r local_ref local_sha remote_ref remote_sha; do
    if [ "$remote_ref" = "refs/heads/main" ] || [ "$remote_ref" = "refs/heads/master" ]; then
        if ! bash scripts/push_gate.sh; then
            exit 1
        fi
    fi
done
exit 0
"""

# Stand-in for the full gate: records that it ran; exit code is controllable.
_STUB_GATE = """#!/usr/bin/env bash
echo ran >> "$STUB_GATE_MARKER"
exit "${STUB_GATE_EXIT:-0}"
"""


# --------------------------------------------------------------------------
# Helpers
# --------------------------------------------------------------------------

def _base_env(tmp_path: Path) -> dict[str, str]:
    env = os.environ.copy()
    for key in list(env):
        if key.startswith(("GIT_", "AIDUMEI_SCAN_", "AIDUMEI_IDENTITY_")):
            env.pop(key)
    empty = tmp_path / "empty.gitconfig"
    empty.touch()
    # Never read the developer's global/system git config (hooksPath, signing).
    env["GIT_CONFIG_GLOBAL"] = str(empty)
    env["GIT_CONFIG_NOSYSTEM"] = "1"
    env["HOME"] = str(tmp_path / "home")
    words = tmp_path / "words.txt"
    words.write_text(WORD + "\n", encoding="utf-8")
    env["AIDUMEI_SCAN_WORDLIST"] = str(words)
    env["AIDUMEM_PYTHON"] = sys.executable
    env["STUB_GATE_MARKER"] = str(tmp_path / "gate-ran.txt")
    return env


def _git(repo: Path, *args: str, env: dict[str, str], check: bool = True,
         ident: tuple[str, str] | None = None) -> subprocess.CompletedProcess[str]:
    env = dict(env)
    if ident is not None:
        env.update({
            "GIT_AUTHOR_NAME": ident[0], "GIT_AUTHOR_EMAIL": ident[1],
            "GIT_COMMITTER_NAME": ident[0], "GIT_COMMITTER_EMAIL": ident[1],
        })
    result = subprocess.run(["git", *args], cwd=repo, env=env,
                            capture_output=True, text=True, check=False)
    if check and result.returncode:
        raise AssertionError(f"git {args} failed: {result.stdout}{result.stderr}")
    return result


class Fixture:
    def __init__(self, tmp_path: Path, hook: str = "new") -> None:
        self.tmp = tmp_path
        self.env = _base_env(tmp_path)
        self.remote = tmp_path / "remote.git"
        self.work = tmp_path / "work"
        subprocess.run(["git", "init", "-q", "--bare", str(self.remote)],
                       env=self.env, check=True, capture_output=True)
        self.work.mkdir()
        self.git("init", "-q", "-b", "main")
        for key, value in (("commit.gpgsign", "false"), ("tag.gpgsign", "false"),
                           ("user.name", CLEAN[0]), ("user.email", CLEAN[1])):
            self.git("config", key, value)
        scripts = self.work / "scripts"
        scripts.mkdir()
        for name in ("commit_metadata_scan.py", "release_scan.py", "install-hooks.sh"):
            shutil.copy2(SCRIPTS / name, scripts / name)
        (scripts / "push_gate.sh").write_text(_STUB_GATE, encoding="utf-8")
        (self.work / ".gitignore").write_text("scripts/\n", encoding="utf-8")
        self.git("remote", "add", "origin", str(self.remote))
        self.commit("baseline", CLEAN)
        self.git("push", "-q", "--no-verify", "origin", "main")
        if hook == "new":
            result = subprocess.run(["bash", "scripts/install-hooks.sh"], cwd=self.work,
                                    env=self.env, capture_output=True, text=True)
            assert result.returncode == 0, result.stdout + result.stderr
        elif hook == "old":
            hook_file = self.work / ".git" / "hooks" / "pre-push"
            hook_file.write_text(_OLD_HOOK, encoding="utf-8")
            hook_file.chmod(0o755)

    def git(self, *args: str, check: bool = True,
            ident: tuple[str, str] | None = None) -> subprocess.CompletedProcess[str]:
        return _git(self.work, *args, env=self.env, check=check, ident=ident)

    def commit(self, message: str, ident: tuple[str, str]) -> str:
        self.git("commit", "-q", "--allow-empty", "-m", message, ident=ident)
        return self.git("rev-parse", "HEAD").stdout.strip()

    def tag(self, name: str, tagger: tuple[str, str], target: str = "HEAD") -> None:
        self.git("tag", "-a", name, "-m", f"release {name}", target, ident=tagger)

    def push(self, *refspecs: str, **extra: str) -> subprocess.CompletedProcess[str]:
        env = dict(self.env, **extra)
        return subprocess.run(["git", "push", "origin", *refspecs], cwd=self.work,
                              env=env, capture_output=True, text=True, check=False)

    def remote_has(self, ref: str) -> bool:
        return subprocess.run(["git", "--git-dir", str(self.remote), "rev-parse", "--verify",
                               "-q", ref], env=self.env, capture_output=True).returncode == 0

    @property
    def gate_ran(self) -> bool:
        return Path(self.env["STUB_GATE_MARKER"]).exists()


