def test_allowlist_env_entries_are_split_on_semicolons() -> None:
    allow = cms.load_identity_allowlist(
        [], env={"AIDUMEI_IDENTITY_ALLOWLIST": "A Bot <a@example.org>; B <b@example.org>\n"})
    assert allow == {(b"A Bot", b"a@example.org"), (b"B", b"b@example.org")}


def _line(local_ref: str, local_sha: str, remote_ref: str, remote_sha: str) -> str:
    return f"{local_ref} {local_sha} {remote_ref} {remote_sha}"


ZERO = "0" * 40


def test_pre_push_excludes_commits_the_remote_already_has(repo: Fixture) -> None:
    # A private identity that is already public on origin/main is history, not news.
    repo.commit("old private", ("Synthetic Tagger", "tagger@192.0.2.10"))
    repo.git("push", "-q", "--no-verify", "origin", "main")
    old = repo.git("rev-parse", "HEAD").stdout.strip()
    new = repo.commit("clean", CLEAN)

    counts = cms.scan_pre_push(repo.work, "origin",
                               [_line("refs/heads/main", new, "refs/heads/main", old)], [WORD],
                               require_allowlist=True)
    assert (counts.refs, counts.commits, counts.forbidden_domains, counts.blocked) == (1, 1, 0, False)


def test_pre_push_scans_tags_and_other_branches(repo: Fixture) -> None:
    repo.git("checkout", "-q", "-b", "feature")
    feature = repo.commit("feature", ("Ops", "ops@build-01.internal"))
    repo.tag("v9.9", ("Synthetic Tagger", "tagger@192.0.2.10"))
    tag_sha = repo.git("rev-parse", "refs/tags/v9.9").stdout.strip()

    counts = cms.scan_pre_push(repo.work, "origin", [
        _line("refs/heads/feature", feature, "refs/heads/feature", ZERO),
        _line("refs/tags/v9.9", tag_sha, "refs/tags/v9.9", ZERO),
    ], [WORD])
    # One new commit (author + committer) and one tagger, all on private hosts.
    assert (counts.refs, counts.commits, counts.tags, counts.forbidden_domains) == (2, 1, 1, 3)


def test_pre_push_deletion_pushes_nothing(repo: Fixture) -> None:
    head = repo.git("rev-parse", "HEAD").stdout.strip()
    counts = cms.scan_pre_push(repo.work, "origin",
                               [_line("(delete)", ZERO, "refs/heads/gone", head)], [WORD])
    assert (counts.refs, counts.commits, counts.tags, counts.blocked) == (1, 0, 0, False)


@pytest.mark.parametrize("line", [
    "refs/heads/main deadbeef refs/heads/main " + ZERO,
    "only three fields",
    "refs/heads/main " + "g" * 40 + " refs/heads/main " + ZERO,
])
def test_pre_push_malformed_input_is_unverifiable(repo: Fixture, line: str) -> None:
    with pytest.raises(cms.MetadataScanError):
        cms.scan_pre_push(repo.work, "origin", [line], [WORD])


@pytest.mark.parametrize("remote", ["", "--all", "orig*"])
def test_pre_push_rejects_unsafe_remote_names(repo: Fixture, remote: str) -> None:
    with pytest.raises(cms.MetadataScanError):
        cms.scan_pre_push(repo.work, remote, [], [WORD])


def test_cli_reports_counts_without_leaking_identities(repo: Fixture) -> None:
    repo.tag("v9.9", ("Synthetic Private", "tagger@192.0.2.10"))
    head = repo.git("rev-parse", "HEAD").stdout.strip()
    result = subprocess.run(
        [sys.executable, str(SCRIPTS / "commit_metadata_scan.py"), "--base", head,
         "--head", head, "--tag", "v9.9", "--require-allowlist"],
        cwd=repo.work, env=repo.env, capture_output=True, text=True, check=False)
    assert result.returncode == 1, result.stdout + result.stderr
    output = result.stdout + result.stderr
    for secret in ("Synthetic Private", "tagger@", "192.0.2.10"):
        assert secret not in output


# --------------------------------------------------------------------------
# The real pre-push hook, driven by real `git push`
# --------------------------------------------------------------------------

def test_hook_blocks_other_branch_with_internal_host_author(tmp_path: Path) -> None:
    fx = Fixture(tmp_path)
    fx.git("checkout", "-q", "-b", "feature")
    fx.commit("feature", ("Ops", "ops@build-01.internal"))

    result = fx.push("feature")

    assert result.returncode != 0, result.stdout + result.stderr
    assert FORBIDDEN_HIT.search(result.stdout) and UNVERIFIABLE not in result.stdout
    assert not fx.remote_has("refs/heads/feature")
    assert not fx.gate_ran  # the identity gate stops it before any full gate


def test_negative_control_old_hook_pushed_that_branch(tmp_path: Path) -> None:
    fx = Fixture(tmp_path, hook="old")
    fx.git("checkout", "-q", "-b", "feature")
    fx.commit("feature", ("Ops", "ops@build-01.internal"))

    result = fx.push("feature")

    assert result.returncode == 0, result.stdout + result.stderr
    assert fx.remote_has("refs/heads/feature")


@pytest.mark.parametrize("tagger", [("Synthetic Tagger", "tagger@192.0.2.10"),
                                    ("root", "root@iZbp1a2b3c4d5e6f7g8h9Z")])
def test_hook_blocks_tag_with_private_tagger(tmp_path: Path, tagger: tuple[str, str]) -> None:
    fx = Fixture(tmp_path)
    fx.tag("v9.9", tagger)

    result = fx.push("refs/tags/v9.9")

    assert result.returncode != 0, result.stdout + result.stderr
    assert FORBIDDEN_HIT.search(result.stdout) and UNVERIFIABLE not in result.stdout
    assert not fx.remote_has("refs/tags/v9.9")


def test_negative_control_old_hook_pushed_the_private_tag(tmp_path: Path) -> None:
    fx = Fixture(tmp_path, hook="old")
    fx.tag("v9.9", ("Synthetic Tagger", "tagger@192.0.2.10"))

    result = fx.push("refs/tags/v9.9")

    assert result.returncode == 0, result.stdout + result.stderr
    assert fx.remote_has("refs/tags/v9.9")


def test_hook_blocks_identity_outside_allowlist(tmp_path: Path) -> None:
    fx = Fixture(tmp_path)
    fx.git("checkout", "-q", "-b", "feature")
    fx.commit("contractor", ("Dev", "dev@example.com"))

    blocked = fx.push("feature")
    assert blocked.returncode != 0
    assert NOT_ALLOWLISTED_HIT.search(blocked.stdout) and not FORBIDDEN_HIT.search(blocked.stdout)
    assert not fx.remote_has("refs/heads/feature")
    extended = fx.push("feature", AIDUMEI_IDENTITY_ALLOWLIST="Dev <dev@example.com>")
    assert extended.returncode == 0, extended.stdout + extended.stderr


def test_hook_passes_clean_refs_and_runs_full_gate_only_for_main(tmp_path: Path) -> None:
    fx = Fixture(tmp_path)
    fx.git("checkout", "-q", "-b", "feature")
    fx.commit("feature", CLEAN)
    fx.tag("v9.9", CLEAN)

    assert fx.push("feature", "refs/tags/v9.9").returncode == 0
    assert fx.remote_has("refs/heads/feature") and fx.remote_has("refs/tags/v9.9")
    assert not fx.gate_ran

    fx.git("checkout", "-q", "main")
    fx.commit("main work", CLEAN)
    result = fx.push("main")
    assert result.returncode == 0, result.stdout + result.stderr
    assert fx.gate_ran


def test_hook_keeps_full_gate_failure_blocking_main(tmp_path: Path) -> None:
    fx = Fixture(tmp_path)
    fx.commit("main work", CLEAN)
    before = subprocess.run(["git", "--git-dir", str(fx.remote), "rev-parse", "refs/heads/main"],
                            env=fx.env, capture_output=True, text=True).stdout

    result = fx.push("main", STUB_GATE_EXIT="1")

    assert result.returncode != 0 and fx.gate_ran
    after = subprocess.run(["git", "--git-dir", str(fx.remote), "rev-parse", "refs/heads/main"],
                           env=fx.env, capture_output=True, text=True).stdout
    assert before == after


def test_hook_fails_closed_without_wordlist(tmp_path: Path) -> None:
    fx = Fixture(tmp_path)
    fx.git("checkout", "-q", "-b", "feature")
    fx.commit("feature", CLEAN)
    fx.env.pop("AIDUMEI_SCAN_WORDLIST")  # default path under the empty HOME is absent

    result = fx.push("feature")
    assert result.returncode != 0 and UNVERIFIABLE in result.stdout
    assert not fx.remote_has("refs/heads/feature")


# --------------------------------------------------------------------------
# install-hooks.sh itself
# --------------------------------------------------------------------------

def _install(cwd: Path, env: dict[str, str], *args: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run(["bash", str(SCRIPTS / "install-hooks.sh"), *args], cwd=cwd,
                          env=env, capture_output=True, text=True, check=False)


def test_install_hooks_supports_linked_worktrees(tmp_path: Path) -> None:
    fx = Fixture(tmp_path, hook="none")
    wt = tmp_path / "wt"
    fx.git("worktree", "add", "-q", "-b", "side", str(wt))
    assert (wt / ".git").is_file()  # linked worktree: .git is a file

    result = _install(wt, fx.env)

    assert result.returncode == 0, result.stdout + result.stderr
    hook = fx.work / ".git" / "hooks" / "pre-push"
    assert hook.is_file() and os.access(hook, os.X_OK)
    assert _install(wt, fx.env, "--check").returncode == 0
    assert subprocess.run(["bash", "-n", str(hook)], capture_output=True).returncode == 0


def test_install_hooks_upgrades_old_hook_and_refuses_foreign_hook(tmp_path: Path) -> None:
    fx = Fixture(tmp_path, hook="old")
    hook = fx.work / ".git" / "hooks" / "pre-push"

    assert _install(fx.work, fx.env, "--check").returncode == 1  # old version is not current
    assert _install(fx.work, fx.env).returncode == 0
    assert "--pre-push" in hook.read_text(encoding="utf-8")
    assert _install(fx.work, fx.env, "--check").returncode == 0

    foreign = "#!/bin/sh\necho someone else's hook\n"
    hook.write_text(foreign, encoding="utf-8")
    assert _install(fx.work, fx.env).returncode == 1
    assert hook.read_text(encoding="utf-8") == foreign


def test_push_gate_uses_tag_scan_and_allowlist_mode() -> None:
    source = (SCRIPTS / "push_gate.sh").read_text(encoding="utf-8")
    call = source[source.index("scripts/commit_metadata_scan.py"):]
    call = call[:call.index("|| fail")]
    assert "--tags-in-range" in call and "--require-allowlist" in call
    assert subprocess.run(["bash", "-n", str(SCRIPTS / "push_gate.sh")]).returncode == 0
